from dataclasses import dataclass

@dataclass
class Balance:
    cents: int
    def withdraw(self, amount):
        if amount < 0 or amount > self.cents:
            return False
        self.cents -= amount
        return True

b = Balance(500)
print(b.withdraw(200), b.cents, b.withdraw(400))

def divide_total(total: int, parts: int) -> int:
    if parts <= 0:
        raise ValueError("parts must be positive")
    return total // parts

try:
    print(divide_total(10, 0))
except ValueError as error:
    print(type(error).__name__)

def add_tax(cents, rate):
    if cents < 0 or rate < 0: raise ValueError("non-negative values required")
    return cents + (cents * rate // 100)

print(add_tax(1000, 15))
